def signal(obs):
    # IDX imbalance momentum
    # obs.hist with fields: imbalance
    imb = obs.hist('IDX','imbalance',20)
    if imb is None or len(imb)<10:
        return {}
    # handle NaN
    last = imb[-1]
    if np.isnan(last):
        return {}
    # smooth with 5-bar mean to reduce noise
    vals = imb[-5:]
    vals = vals[~np.isnan(vals)]
    if len(vals)==0:
        return {}
    sig = float(np.mean(vals))
    # sig in [-1,1] already imbalance range roughly +-1, but std 0.239
    # scale: 0.5 imbalance = full position? Clip
    # Map sig -> target: target = clip(sig * scale, -1,1)
    # scale 2 => 0.5 ->1
    target = max(-1,min(1, sig * 2.0))
    # threshold small imbalance -> no trade to save costs
    if abs(sig) < 0.10:
        target = 0
    return {'IDX': target}

def signal(obs):
    out={}
    # state for hysteresis
    # C momentum - primary driver, cheaper venue
    try:
        mC = obs.hist('C','mid',40)
        if mC is not None and len(mC) >= 31:
            # past 30 steps
            if not np.isnan(mC[-1]) and not np.isnan(mC[-31]):
                past = float(mC[-1] - mC[-31])
                # threshold ~ 10 cents (~1.1 std, edge ~4.5 cents > half spread)
                if past > 10:
                    out['C'] = 1.0
                    out['C.X'] = 0.0
                elif past < -10:
                    out['C'] = -1.0
                    out['C.X'] = 0.0
                else:
                    # hysteresis: keep previous if moderate momentum
                    prev = obs.state.get('C_prev', 0)
                    if past > 5 and prev > 0:
                        out['C'] = 1.0
                        out['C.X'] = 0.0
                    elif past < -5 and prev < 0:
                        out['C'] = -1.0
                        out['C.X'] = 0.0
                    else:
                        out['C'] = 0.0
                        out['C.X'] = 0.0
                obs.state['C_prev'] = out.get('C', 0)
    except:
        pass
    # B momentum - weaker but similar, helps diversification
    try:
        mB = obs.hist('B','mid',35)
        if mB is not None and len(mB) >= 31:
            if not np.isnan(mB[-1]) and not np.isnan(mB[-31]):
                pastB = float(mB[-1] - mB[-31])
                if pastB > 8:
                    out['B'] = 0.7
                    out['B.X'] = 0.0
                elif pastB < -8:
                    out['B'] = -0.7
                    out['B.X'] = 0.0
                else:
                    prevB = obs.state.get('B_prev', 0)
                    if pastB > 4 and prevB > 0:
                        out['B'] = 0.7
                        out['B.X'] = 0.0
                    elif pastB < -4 and prevB < 0:
                        out['B'] = -0.7
                        out['B.X'] = 0.0
                    else:
                        out['B'] = 0.0
                        out['B.X'] = 0.0
                obs.state['B_prev'] = out.get('B', 0)
    except:
        pass
    # A - very small drift, trade only large moves
    try:
        mA = obs.hist('A','mid',35)
        if mA is not None and len(mA) >= 31:
            if not np.isnan(mA[-1]) and not np.isnan(mA[-31]):
                pastA = float(mA[-1] - mA[-31])
                if pastA > 9:
                    out['A'] = 0.5
                    out['A.X'] = 0.0
                elif pastA < -9:
                    out['A'] = -0.5
                    out['A.X'] = 0.0
                else:
                    # flat
                    if 'A' not in out:
                        out['A'] = 0.0
                        out['A.X'] = 0.0
    except:
        pass
    # IDX trend filter long term to capture drift with low turnover
    try:
        mI = obs.hist('IDX','mid',70)
        if mI is not None and len(mI) >= 61:
            if not np.isnan(mI[-1]) and not np.isnan(np.nanmean(mI[-61:-1])):
                ma = float(np.nanmean(mI[-61:-1]))
                diff = float(mI[-1] - ma)
                if diff > 6:
                    out['IDX'] = 0.6
                elif diff < -6:
                    out['IDX'] = -0.6
                else:
                    # keep small or flat
                    if 'IDX' not in out:
                        out['IDX'] = 0.0
    except:
        pass
    # keep bonds flat to avoid noise
    out['BOND2Y'] = 0.0
    out['BOND10Y'] = 0.0
    return out

