def corr(a,b):
    a=np.array(a,dtype=float); b=np.array(b,dtype=float)
    m=np.isfinite(a)&np.isfinite(b)
    a=a[m]; b=b[m]
    if len(a)<10 or np.std(a)==0 or np.std(b)==0:
        return 0.0
    return float(np.corrcoef(a,b)[0,1])
