    s = obs.state
    cur = s.get('pos', 0.0)
    try:
        av=a[-1]; bv=b[-1]; cv=c[-1]; iv=i[-1]
    except:
        return {}
    if av!=av or bv!=bv or cv!=cv or iv!=iv:
        return {}
