                    out['B.X'] = 0.0
                if 'IDX' not in out:
                    out['IDX'] = 0.0
                else:
                    out.setdefault('IDX', 0.0)
        else:
            out.setdefault('IDX', 0.0)
            out.setdefault('A', 0.0); out.setdefault('A.X', 0.0)
            out.setdefault('B', 0.0); out.setdefault('B.X', 0.0)
    except:
        out.setdefault('IDX', 0.0)
        out.setdefault('A', 0.0); out.setdefault('A.X', 0.0)
        out.setdefault('B', 0.0); out.setdefault('B.X', 0.0)

    # ensure all venues defined
    for k in ['A','A.X','B','B.X','C','C.X','IDX']:
        if k not in out:
            out[k] = 0.0
    out['BOND2Y'] = 0.0
    out['BOND10Y'] = 0.0
    return out

