def stats(arr):
    v=arr[~np.isnan(arr)]
    if len(v)==0:
        return (float('nan'), float('nan'), float('nan'), float('nan'))
    return (float(np.nanmean(v)), float(np.nanstd(v)), float(np.nanmin(v)), float(np.nanmax(v)))
def ac(x, lag):
    xv=x[~np.isnan(x)]
    if len(xv)<lag+10:
        return float('nan')
    return float(np.corrcoef(xv[:-lag], xv[lag:])[0,1])
