result={}
for pair in [('A','A.X'),('B','B.X'),('C','C.X')]:
    a=H[pair[0]]['mid']; b=H[pair[1]]['mid']
    spread = a - b
    m,s,mi,ma = stats(spread)
    result[pair[0]+'_vs_'+pair[1]+'_mean']=m
    result[pair[0]+'_vs_'+pair[1]+'_std']=s
    result[pair[0]+'_vs_'+pair[1]+'_min']=mi
    result[pair[0]+'_vs_'+pair[1]+'_max']=ma
    result[pair[0]+'_vs_'+pair[1]+'_ac1']=ac(spread,1)
    result[pair[0]+'_vs_'+pair[1]+'_ac10']=ac(spread,10)
    result[pair[0]+'_vs_'+pair[1]+'_ac50']=ac(spread,50)
    # correlation spread vs future change of spread (mean reversion)
    future=[]
    now=[]
    for i in range(n-10):
        if not np.isnan(spread[i]) and not np.isnan(spread[i+10]):
            now.append(spread[i])
            future.append(spread[i+10]-spread[i])
    if len(now)>100:
        result[pair[0]+'_spread_vs_change_corr10']=float(np.corrcoef(np.array(now), np.array(future))[0,1])
    # also future return of primary vs spread
    fr=[]
    sp=[]
    for i in range(n-10):
        if not np.isnan(spread[i]) and not np.isnan(a[i]) and not np.isnan(a[i+10]):
            sp.append(spread[i])
            fr.append(a[i+10]-a[i])
    if len(sp)>100:
        result[pair[0]+'_spread_vs_future_primary_corr10']=float(np.corrcoef(np.array(sp), np.array(fr))[0,1])
    # chunks
    for k in range(3):
        s_idx=k*1250; e=min((k+1)*1250,n)
        result[pair[0]+f'_mean_chunk{k}']=float(np.nanmean(spread[s_idx:e]))
        result[pair[0]+f'_std_chunk{k}']=float(np.nanstd(spread[s_idx:e]))

