                obs.state[a+'_t']=0
            else:
                # hold previous
                if prevA==1:
                    out[a]= w
                    out[b]= -w
                elif prevA==-1:
                    out[a]= -w
                    out[b]= w
                else:
                    out[a]=0.0
                    out[b]=0.0
        except:
            pass
    pair('A','A.X',12,3,0.8)
    pair('B','B.X',10,3,0.7)
