    hb = obs.hist('B', 'mid', 5)
    hc = obs.hist('C', 'mid', 5)
    hi = obs.hist('IDX', 'mid', 5)
    if ha is None or hb is None or hc is None or hi is None:
        return {}
    if len(ha) < 5 or len(hb) < 5 or len(hc) < 5 or len(hi) < 5:
        return {}
    a, b, c, i = ha[-1], hb[-1], hc[-1], hi[-1]
    if not (a == a and b == b and c == c and i == i):
        return {}
    syn = 0.3333*a + 0.6667*b + 0.1667*c
    gap = i - syn
    st = obs.state
    pos = st.get('p', 0)
    ein = 25.0
    xit = 5.0
    if pos == 0:
        if gap > ein:
            pos = -1
        elif gap < -ein:
            pos = 1
    elif pos == -1:
        if gap < xit:
            pos = 0
    elif pos == 1:
        if gap > -xit:
            pos = 0
    st['p'] = pos
    if pos == -1:
        return {'IDX': -1.0, 'A': 0.33, 'B': 0.67, 'C': 0.17}
    if pos == 1:
        return {'IDX': 1.0, 'A': -0.33, 'B': -0.67, 'C': -0.17}
    return {'IDX': 0.0, 'A': 0.0, 'B': 0.0, 'C': 0.0}

