def signal(obs):
    ha = obs.hist('A', 'mid', 220)
    hb = obs.hist('B', 'mid', 220)
    hc = obs.hist('C', 'mid', 220)
    hi = obs.hist('IDX', 'mid', 220)
    if ha is None or hb is None or hc is None or hi is None:
        return {}
    n = min(len(ha), len(hb), len(hc), len(hi))
    if n < 210:
        return {}
    a, b, c, i = ha[-1], hb[-1], hc[-1], hi[-1]
    if not (a == a and b == b and c == c and i == i):
        return {}
    syn = 0.3333*a + 0.6667*b + 0.1667*c
    gap = i - syn
    # rolling std of gap over last 200 steps using available mids
    s = 0.0
    m = 0.0
    cnt = 0
    for k in range(1, 201):
        if n-1-k < 0:
            break
        a0, b0, c0, i0 = ha[n-1-k], hb[n-1-k], hc[n-1-k], hi[n-1-k]
        if not (a0 == a0 and b0 == b0 and c0 == c0 and i0 == i0):
            continue
        g0 = i0 - (0.3333*a0 + 0.6667*b0 + 0.1667*c0)
        m += g0
        s += g0*g0
        cnt += 1
    if cnt < 100:
        return {}
    mean = m / cnt
    var = s / cnt - mean*mean
    if not (var == var) or var <= 0:
        return {}
    sd = var ** 0.5
    if not (sd == sd) or sd < 5.0:
        sd = 5.0
    z = (gap - mean) / sd
    if z > 1.5:
        return {'IDX': -1.0, 'A': 0.33, 'B': 0.67, 'C': 0.17}
    if z < -1.5:
        return {'IDX': 1.0, 'A': -0.33, 'B': -0.67, 'C': -0.17}
    if -0.5 < z < 0.5:
        return {'IDX': 0.0, 'A': 0.0, 'B': 0.0, 'C': 0.0}
    return {}

