def signal(obs):
    s = obs.state
    # hysteresis thresholds in cents
    T_enter = 60.0
    T_exit = 10.0
    try:
        c = obs.last('C', 'mid')
        cx = obs.last('C.X', 'mid')
    except Exception:
        return {}
    if c is None or cx is None:
        return {}
    # NaN check
    if not (c == c) or not (cx == cx):
        return {}
    spread = c - cx
    cur = s.get('pos', 0)  # +1 long spread, -1 short spread, 0 flat
    if cur == 0:
        if spread > T_enter:
            cur = -1
        elif spread < -T_enter:
            cur = 1
    elif cur == -1:
        if spread <= T_exit:
            # revert to flat; check opposite entry immediately
            if spread < -T_enter:
                cur = 1
            elif spread <= T_exit and spread > -T_enter:
                # exit when back near zero; use small deadband
                if spread < T_exit:
                    cur = 0
                else:
                    cur = 0
            else:
                cur = -1
            if spread <= 10:
                # standard exit: if spread <= exit, flatten unless strong opposite
                if spread < -T_enter:
                    cur = 1
                else:
                    cur = 0
    elif cur == 1:
        if spread >= -T_exit:
            if spread > T_enter:
                cur = -1
            else:
                cur = 0
    s['pos'] = cur
    if cur == 1:
        return {'C': 1.0, 'C.X': -1.0}
    elif cur == -1:
        return {'C': -1.0, 'C.X': 1.0}
    else:
        return {'C': 0.0, 'C.X': 0.0}

