def signal(obs):
    out={}
    # cross arb only
    try:
        # A pair
        mA = obs.hist('A','mid',5)
        mAX = obs.hist('A.X','mid',5)
        if mA is not None and mAX is not None and len(mA)>0 and len(mAX)>0:
            a = float(mA[-1]); ax = float(mAX[-1])
            if not np.isnan(a) and not np.isnan(ax):
                diff = a - ax
                prev = obs.state.get('A_pos',0)
                # costs: total ~14.8, so entry 15 exit 5
                if diff > 15:
                    out['A'] = -0.7; out['A.X'] = 0.7
                    obs.state['A_pos'] = -1
                elif diff < -15:
                    out['A'] = 0.7; out['A.X'] = -0.7
                    obs.state['A_pos'] = 1
                elif abs(diff) < 5:
                    out['A'] = 0.0; out['A.X'] = 0.0
                    obs.state['A_pos'] = 0
                else:
                    # hold
                    if prev == -1 and diff > 5:
                        out['A'] = -0.7; out['A.X'] = 0.7
                    elif prev == 1 and diff < -5:
                        out['A'] = 0.7; out['A.X'] = -0.7
                    else:
                        out['A'] = 0.0; out['A.X'] = 0.0
                        obs.state['A_pos'] = 0
        # B pair
        mB = obs.hist('B','mid',5)
        mBX = obs.hist('B.X','mid',5)
        if mB is not None and mBX is not None and len(mB)>0 and len(mBX)>0:
            b = float(mB[-1]); bx = float(mBX[-1])
            if not np.isnan(b) and not np.isnan(bx):
                diff = b - bx
                prev = obs.state.get('B_pos',0)
                if diff > 12:
                    out['B'] = -0.7; out['B.X'] = 0.7
                    obs.state['B_pos'] = -1
                elif diff < -12:
                    out['B'] = 0.7; out['B.X'] = -0.7
                    obs.state['B_pos'] = 1
                elif abs(diff) < 4:
                    out['B'] = 0.0; out['B.X'] = 0.0
                    obs.state['B_pos'] = 0
                else:
                    if prev == -1 and diff > 4:
                        out['B'] = -0.7; out['B.X'] = 0.7
                    elif prev == 1 and diff < -4:
                        out['B'] = 0.7; out['B.X'] = -0.7
                    else:
                        out['B'] = 0.0; out['B.X'] = 0.0
                        obs.state['B_pos'] = 0
        # C pair
