    out = {}
    try:
        h = obs.hist('A', 'mid', 80)
        if h is not None and len(h) >= 60:
            past = h[-1] - h[-51]
            if past == past:
                if past > 30.0:
                    out['A'] = 1.0
                elif past < -30.0:
                    out['A'] = -1.0
                elif abs(past) < 5.0:
                    out['A'] = 0.0
    except Exception:
        pass
    try:
        ia = obs.last('A', 'mid')
        ib = obs.last('B', 'mid')
        ic = obs.last('C', 'mid')
        ix = obs.last('IDX', 'mid')
    except Exception:
        return out
    ok = True
    for v in (ia, ib, ic, ix):
        if v != v:
            ok = False
    if not ok:
        return out
